import{_ as s,a0 as p,w as i,s as u,ao as a,I as r,a1 as n,A as e,x as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"为你的开源项目举办一场文档马拉松 | LCTT x X-CMD","titleTemplate":false,"description":"为你的开源项目举办一场文档马拉松 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为你的开源项目举办一场文档马拉松 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为你的开源项目举办一场文档马拉松 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230428.2 ⭐️⭐️ 3 reasons to host a docathon for your open source project","title":"为你的开源项目举办一场文档马拉松","tag":"202306","desc":""},"relativePath":"202306/20230428.2 ⭐️⭐️ 3 reasons to host a docathon for your open source project.md","filePath":"[post].md"}'),d={name:"202306/20230428.2 ⭐️⭐️ 3 reasons to host a docathon for your open source project.md"};function f(m,t,b,T,g,k){const l=p("Link");return i(),u("div",null,[t[29]||(t[29]=a('<h1 id="为你的开源项目举办一场文档马拉松" tabindex="-1">为你的开源项目举办一场文档马拉松 <a class="header-anchor" href="#为你的开源项目举办一场文档马拉松" aria-label="Permalink to “为你的开源项目举办一场文档马拉松”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202306/02/001044rfszwiujown8fd3j.jpg" alt=""></p><blockquote><p>文档马拉松是为你的开源项目制作或改进文档的一个好方法。</p></blockquote><p>你的开源项目的文档对你的客户至关重要。你的目标受众必须了解你的项目的目的和如何使用它，而文档是弥合这一差距的工具。一个项目很少有真正完成的时候，所以随着你项目的不断改进，资源的维护和更新同样重要。</p><p>但是，当你有大量的文档需要维护，但又缺乏资源来保持它的时效性时，会发生什么？答案很简单：举办一个 <ruby>文档马拉松<rt>docathon</rt></ruby>！</p><h3 id="什么是文档马拉松" tabindex="-1">什么是文档马拉松？ <a class="header-anchor" href="#什么是文档马拉松" aria-label="Permalink to “什么是文档马拉松？”">​</a></h3><p>文档马拉松就像 <ruby>黑客马拉松<rt>hackathon</rt></ruby>。黑客马拉松是工程师和社区领袖聚集在一起改进或添加新功能到一个现有的应用的活动。在一个文档马拉松中，同样的合作集中在改进文档上。</p><p>文档马拉松可以填补内容上的空白，重组大型文档集，修复失效的链接，或者只是纠正错别字。举办文档马拉松的目的是为了在相对短的时间内改进大量的文档。</p><p>一些产品文档的例子包括：</p>',9)),r("ul",null,[t[2]||(t[2]=r("li",null,"培训手册",-1)),t[3]||(t[3]=r("li",null,"用户手册",-1)),t[4]||(t[4]=r("li",null,"安装指南",-1)),t[5]||(t[5]=r("li",null,"故障排除指南",-1)),t[6]||(t[6]=r("li",null,"快速入门指南",-1)),r("li",null,[n(l,{href:"https://www.redhat.com/en/topics/api/what-are-application-programming-interfaces?intcmp=7013a000002qLH8AAM"},{default:e(()=>[...t[0]||(t[0]=[o("API",-1)])]),_:1}),t[1]||(t[1]=o(" 文档",-1))]),t[7]||(t[7]=r("li",null,"教程",-1))]),t[30]||(t[30]=r("p",null,"在我的组织里，我们的文档团队举办了一次文档马拉松，成功地修改了 102 页的安装指南。这次文档马拉松使我们能够专注于项目的范围，即重新组织简化，删除重复的内容，并遵循客户旅程。举办文档马拉松给我的团队留下了深刻的印象，并提高了客户的成功率。",-1)),t[31]||(t[31]=r("h3",{id:"_3-件你可以通过文档马拉松实现的事情",tabindex:"-1"},[o("3 件你可以通过文档马拉松实现的事情 "),r("a",{class:"header-anchor",href:"#_3-件你可以通过文档马拉松实现的事情","aria-label":"Permalink to “3 件你可以通过文档马拉松实现的事情”"},"​")],-1)),t[32]||(t[32]=r("p",null,"以下是我举办文档马拉松的三大理由：",-1)),t[33]||(t[33]=r("h4",{id:"_1、减少积压",tabindex:"-1"},[o("1、减少积压 "),r("a",{class:"header-anchor",href:"#_1、减少积压","aria-label":"Permalink to “1、减少积压”"},"​")],-1)),r("p",null,[t[9]||(t[9]=o("大多数文档必须随着它所支持的产品的发展而发展。随着产品的变化或更新，文档也必须如此。在某些情况下，文档团队与工程团队的发布周期一起发布新版本的文档。随着团队内优先级的改变和 ",-1)),n(l,{href:"https://opensource.com/article/19/7/what-golden-image"},{default:e(()=>[...t[8]||(t[8]=[o("GA 发布",-1)])]),_:1}),t[10]||(t[10]=o(" 的继续，文档团队面临着跟上新功能、错误修复和任务完成的挑战。被遗弃的变化成为积压的一部分，一种需要在以后完成的工作的积累。",-1))]),t[34]||(t[34]=a('<blockquote><p><strong>提示：</strong> 在文档马拉松期间，参与者可以对积压的项目进行分流，并在列表中完成它们。非技术性的参与者可以从事与错别字、失效的链接和其他文本相关问题的修复工作。</p></blockquote><h4 id="_2、改造大型指南" tabindex="-1">2、改造大型指南 <a class="header-anchor" href="#_2、改造大型指南" aria-label="Permalink to “2、改造大型指南”">​</a></h4><p>当你的文档团队意识到是时候修改指南的时候，它可能已经有好几章，好几百页了。一旦制定了内容计划，重组的复杂性就开始了。重组大量的文档并不适合胆小的人。</p><blockquote><p><strong>提示：</strong> 组建一个团队来领导文档马拉松，并为不同团队或部门的全组织参与提供奖励。根据工作范围和时间限制，你的团队可以在比你预期更短的时间内成功重组整个指南。</p></blockquote><h4 id="_3、跨职能团队之间的合作" tabindex="-1">3、跨职能团队之间的合作 <a class="header-anchor" href="#_3、跨职能团队之间的合作" aria-label="Permalink to “3、跨职能团队之间的合作”">​</a></h4><p>一个组织内的不同小组孤立地工作是很常见的。工程、产品、客户支持、营销和文档团队可能没有像他们应该的那样经常在项目上进行协作。</p><p>想象一下，举办一次活动，每个团队成员都可以利用他们的专业知识来改善产品文档。文档马拉松促进了主题专家（SME）的多样性、实时协作和沟通。它们还允许一个包容性的环境，居住在不同地理位置的人可以亲自或远程参与。你的文件会得到具有不同观点和专业的专家的关注，最大限度地减少孤立的孤岛、无意识的偏见和倦怠。</p><blockquote><p><strong>提示：</strong> 使跨职能的团队为了一个共同的事业走到一起。</p></blockquote><h3 id="文档马拉松" tabindex="-1">文档马拉松 <a class="header-anchor" href="#文档马拉松" aria-label="Permalink to “文档马拉松”">​</a></h3>',9)),r("p",null,[t[12]||(t[12]=o("下一次，当你的团队有一个似乎无法克服的积压工作，或者被赋予重组一个巨大的文档项目的任务时，考虑举办一个文档马拉松。这很容易，而且它的生产力可能会让你吃惊。关于举办这样的活动的更多信息，请阅读 Tiffany Long 写的很棒的 ",-1)),n(l,{href:"https://opensource.com/downloads/hackathon-guide?intcmp=7013a000002qLH8AAM"},{default:e(()=>[...t[11]||(t[11]=[o("举办黑客马拉松的 10 步指南",-1)])]),_:1}),t[13]||(t[13]=o("。",-1))]),t[35]||(t[35]=r("p",null,[r("em",null,"（题图：MJ/1284f6fb-91e9-4799-8773-ee7f51fd87c9）")],-1)),t[36]||(t[36]=r("hr",null,null,-1)),r("p",null,[t[15]||(t[15]=o("via: ",-1)),n(l,{href:"https://opensource.com/article/23/4/open-source-docathon"},{default:e(()=>[...t[14]||(t[14]=[o("https://opensource.com/article/23/4/open-source-docathon",-1)])]),_:1})]),r("p",null,[t[20]||(t[20]=o("作者：",-1)),n(l,{href:"https://opensource.com/users/lmalivert"},{default:e(()=>[...t[16]||(t[16]=[o("Lydie Modé-Malivert",-1)])]),_:1}),t[21]||(t[21]=o(" 选题：",-1)),n(l,{href:"https://github.com/lkxed/"},{default:e(()=>[...t[17]||(t[17]=[o("lkxed",-1)])]),_:1}),t[22]||(t[22]=o(" 译者：",-1)),n(l,{href:"https://github.com/geekpi"},{default:e(()=>[...t[18]||(t[18]=[o("geekpi",-1)])]),_:1}),t[23]||(t[23]=o(" 校对：",-1)),n(l,{href:"https://github.com/wxy"},{default:e(()=>[...t[19]||(t[19]=[o("wxy",-1)])]),_:1})]),r("p",null,[t[26]||(t[26]=o("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[24]||(t[24]=[o("LCTT",-1)])]),_:1}),t[27]||(t[27]=o(" 原创编译，",-1)),n(l,{href:"https://linux.cn/"},{default:e(()=>[...t[25]||(t[25]=[o("Linux中国",-1)])]),_:1}),t[28]||(t[28]=o(" 荣誉推出",-1))])])}const L=s(d,[["render",f]]);export{P as __pageData,L as default};
